            if op == 1:
                count += 1
                k -= (1 << i)
        i -= 1

    return chr(97 + (count % 26))

def countDigitOne(n: int) -> int:
    if n < 0:
        return 0

    count = 0
    factor = 1
    while factor <= n:
        lower_numbers = n - (n // factor) * factor
        current_digit = (n // factor) % 10
        higher_numbers = n // (factor * 10)

        if current_digit == 0:
            count += higher_numbers * factor
        elif current_digit == 1:
            count += higher_numbers * factor + lower_numbers + 1
        else:
            count += (higher_numbers + 1) * factor

        factor *= 10

    return count

# Example usage:
print(countDigitOne(13))  # Output: 6
print(countDigitOne(0))   # Output: 0

def consecutiveNumbersSum(n: int) -> int:
    if n < 1:
        return 0
    count = 0
    k = 1
    while k * (k - 1) // 2 < n:
        if (n - k * (k - 1) // 2) % k == 0:
            count += 1
        k += 1
    return count

