def maximumScore(nums: List[int], k: int) -> int:
    MOD = 10**9 + 7
    n = len(nums)

    def prime_factors_count(x):
        count = 0
        for i in range(2, int(x**0.5) + 1):
            if x % i == 0:
                count += 1
                while x % i == 0:
                    x //= i
        if x > 1:
            count += 1
        return count

    prime_scores = [prime_factors_count(num) for num in nums]
    indexed_scores = [(prime_scores[i], i, nums[i]) for i in range(n)]
    indexed_scores.sort(key=lambda x: (-x[0], x[1]))

    score = 1

    for i in range(min(k, n)):
        score = (score * indexed_scores[i][2]) % MOD

