def maxIncreasingGroups(usageLimits: List[int]) -> int:
    usageLimits.sort()
    n = len(usageLimits)
    total_groups = 0
    current_group_size = 0

    while True:
        current_group_size += 1
        total_needed = current_group_size
        total_available = 0

        for limit in usageLimits:
            total_available += min(limit, total_needed)
            if total_available >= total_needed:
                break

        if total_available >= total_needed:
            total_groups += 1
            for i in range(n):
                if total_needed <= 0:
                    break
                if usageLimits[i] > 0:
                    used = min(usageLimits[i], total_needed)
                    usageLimits[i] -= used
                    total_needed -= used
        else:
            break

    return total_groups

