def countOfPairs(nums: List[int]) -> int:
    MOD = 10**9 + 7
    n = len(nums)

    dp = [[0] * 51 for _ in range(n + 1)]
    dp[n] = [1] * 51

    for i in range(n - 1, -1, -1):
        for j in range(51):
            if j <= nums[i]:
                dp[i][j] = (dp[i + 1][j] + dp[i][j + 1]) % MOD
            else:
                dp[i][j] = dp[i + 1][j] % MOD

    return dp[0][0]

def kMirror(k: int, n: int) -> int:
    def is_palindrome(s):
        return s == s[::-1]

    def to_base_k(num, k):
        if num == 0:
            return "0"
        digits = []
        while num:
            digits.append(int(num % k))
            num //= k
        return ''.join(str(x) for x in digits[::-1])

    result = []
    count = 0
    num = 1

    while count < n:
        if is_palindrome(str(num)):
            base_k_representation = to_base_k(num, k)
            if is_palindrome(base_k_representation):
                result.append(num)
                count += 1
        num += 1

    return sum(result)
